extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var arena := await instantiate_main_scene()
	if not check("arena_scene", arena != null, "La scena principale arena.tscn deve caricarsi senza errori"):
		return

	var enemy_data_script = load("res://enemy_data.gd")
	if not check("enemy_data_exists", enemy_data_script != null, "Lo script res://enemy_data.gd deve esistere"):
		return

	var wave_data_script = load("res://wave_data.gd")
	if not check("wave_data_exists", wave_data_script != null, "Lo script res://wave_data.gd deve esistere"):
		return

	var enemy_scene_res = load("res://enemy.tscn") as PackedScene
	if not check("enemy_scene_exists", enemy_scene_res != null, "La scena res://enemy.tscn deve esistere"):
		return

	var dummy_data = enemy_data_script.new()
	dummy_data.set("speed", 200.0)
	dummy_data.set("max_health", 30)
	dummy_data.set("damage", 15)

	var enemy = enemy_scene_res.instantiate() as Node2D
	if not check("enemy_instantiate", enemy != null, "La scena enemy.tscn deve potersi istanziare"):
		return

	enemy.set("data", dummy_data)
	arena.add_child(enemy)
	enemy.global_position = Vector2(100, 324)

	var health_node = enemy.find_child("Health")
	if health_node == null:
		health_node = find_by_class(enemy, "Health")

	check("enemy_health", health_node != null, "Il nemico deve contenere un nodo componente Health")

	var player = find_by_name(arena, "Player") as Node2D
	if player != null:
		player.global_position = Vector2(500, 324)
		var start_x: float = enemy.global_position.x
		await wait_physics_frames(10)
		check("enemy_moves", enemy.global_position.x > start_x, "Il nemico deve muoversi verso il giocatore")

	if is_instance_valid(enemy):
		enemy.queue_free()
		await wait_frames(2)

	var custom_enemy_data = enemy_data_script.new()
	custom_enemy_data.set("speed", 100.0)
	custom_enemy_data.set("max_health", 20)
	custom_enemy_data.set("damage", 10)

	var custom_wave = wave_data_script.new()
	var enemy_types_arr: Array = [custom_enemy_data]
	custom_wave.set("enemy_types", enemy_types_arr)
	custom_wave.set("spawn_count", 2)
	custom_wave.set("spawn_interval", 0.1)

	var waves_arr: Array = [custom_wave]
	arena.set("waves", waves_arr)

	await wait_seconds(0.5)

	var enemies = arena.get_tree().get_nodes_in_group("enemies")
	check("spawner_works", enemies.size() >= 1, "La gestione delle ondate deve far nascere i nemici registrandoli nel gruppo 'enemies'")

