class_name Health
extends Node

signal health_changed(new_health: int)
signal died

@export var max_health: int = 100
var current_health: int


func _ready() -> void:
	current_health = max_health


func take_damage(amount: int) -> void:
	if current_health <= 0:
		return
	current_health = maxi(0, current_health - amount)
	health_changed.emit(current_health)
	if current_health == 0:
		died.emit()

extends CharacterBody2D

@export var speed: float = 250.0
@export var bullet_scene: PackedScene = preload("res://bullet.tscn")

@onready var health: Health = $Health

var shoot_cooldown: float = 0.2
var shoot_timer: float = 0.0


func _physics_process(delta: float) -> void:
	shoot_timer -= delta
	var dir := Input.get_vector("move_left", "move_right", "move_up", "move_down")
	velocity = dir * speed
	move_and_slide()

	if Input.is_action_pressed("shoot") and shoot_timer <= 0.0:
		shoot()
		shoot_timer = shoot_cooldown


func shoot() -> void:
	if bullet_scene == null:
		return
	var bullet := bullet_scene.instantiate() as Area2D
	bullet.global_position = global_position
	var target := get_global_mouse_position()
	var dir := (target - global_position).normalized()
	if dir == Vector2.ZERO:
		dir = Vector2.RIGHT
	bullet.set("direction", dir)
	get_parent().add_child(bullet)

class_name EnemyData
extends Resource

@export var speed: float = 100.0
@export var max_health: int = 20
@export var damage: int = 10

class_name WaveData
extends Resource

@export var enemy_types: Array[EnemyData] = []
@export var spawn_count: int = 5
@export var spawn_interval: float = 1.0

class_name Enemy
extends CharacterBody2D

@export var data: EnemyData

@onready var health: Health = $Health

var player: Node2D = null


func _ready() -> void:
	add_to_group("enemies")
	if data:
		health.max_health = data.max_health
		health.current_health = data.max_health

	health.died.connect(_on_died)


func _physics_process(_delta: float) -> void:
	if player == null:
		player = get_parent().get_node_or_null("Player")

	if player:
		var direction := (player.global_position - global_position).normalized()
		var spd := data.speed if data else 100.0
		velocity = direction * spd
		move_and_slide()

		if global_position.distance_to(player.global_position) < 24.0:
			var player_health := player.get_node_or_null("Health") as Health
			if player_health:
				var dmg := data.damage if data else 10
				player_health.take_damage(dmg)
			queue_free()


func _on_died() -> void:
	queue_free()

extends Area2D

@export var speed: float = 500.0
var direction: Vector2 = Vector2.RIGHT
var lifetime: float = 2.0


func _ready() -> void:
	body_entered.connect(_on_body_entered)


func _physics_process(delta: float) -> void:
	position += direction * speed * delta
	lifetime -= delta
	if lifetime <= 0.0:
		queue_free()


func _on_body_entered(body: Node2D) -> void:
	if body.is_in_group("enemies") or body is Enemy:
		var health := body.get_node_or_null("Health") as Health
		if health:
			health.take_damage(10)
		queue_free()
	elif body.name == "Walls":
		queue_free()

extends Node2D

@export var enemy_scene: PackedScene = preload("res://enemy.tscn")
@export var waves: Array[WaveData] = []:
	set(value):
		waves = value
		current_wave_index = 0
		spawned_in_wave = 0
		if not waves.is_empty():
			spawn_timer = waves[0].spawn_interval
		else:
			spawn_timer = 0.0

var current_wave_index: int = 0
var spawned_in_wave: int = 0
var spawn_timer: float = 0.0
var wave_delay_timer: float = 0.0
var waiting_for_next_wave: bool = false


func _ready() -> void:
	if waves.is_empty():
		_setup_default_waves()
	elif not waves.is_empty():
		spawn_timer = waves[0].spawn_interval


func _setup_default_waves() -> void:
	var fast_res = load("res://enemies/fast_enemy.tres") as EnemyData
	var normal_res = load("res://enemies/normal_enemy.tres") as EnemyData
	var tank_res = load("res://enemies/tank_enemy.tres") as EnemyData

	var w1 := WaveData.new()
	w1.spawn_count = 5
	w1.spawn_interval = 1.0
	if normal_res:
		w1.enemy_types.append(normal_res)

	var w2 := WaveData.new()
	w2.spawn_count = 8
	w2.spawn_interval = 0.8
	if fast_res:
		w2.enemy_types.append(fast_res)
	if normal_res:
		w2.enemy_types.append(normal_res)

	var w3 := WaveData.new()
	w3.spawn_count = 12
	w3.spawn_interval = 0.6
	if fast_res:
		w3.enemy_types.append(fast_res)
	if normal_res:
		w3.enemy_types.append(normal_res)
	if tank_res:
		w3.enemy_types.append(tank_res)

	waves = [w1, w2, w3]


func _process(delta: float) -> void:
	if current_wave_index >= waves.size():
		return

	var wave := waves[current_wave_index]

	if waiting_for_next_wave:
		wave_delay_timer -= delta
		if wave_delay_timer <= 0.0:
			waiting_for_next_wave = false
			current_wave_index += 1
			spawned_in_wave = 0
			if current_wave_index < waves.size():
				spawn_timer = waves[current_wave_index].spawn_interval
		return

	if spawned_in_wave < wave.spawn_count:
		spawn_timer -= delta
		if spawn_timer <= 0.0:
			spawn_enemy(wave)
			spawned_in_wave += 1
			spawn_timer = wave.spawn_interval
	else:
		var enemies := get_tree().get_nodes_in_group("enemies")
		if enemies.is_empty():
			waiting_for_next_wave = true
			wave_delay_timer = 2.0


func spawn_enemy(wave: WaveData) -> void:
	if enemy_scene == null or wave.enemy_types.is_empty():
		return
	var enemy := enemy_scene.instantiate() as Enemy
	var type_data: EnemyData = wave.enemy_types.pick_random()
	enemy.data = type_data

	var side := randi() % 4
	var pos := Vector2.ZERO
	match side:
		0: pos = Vector2(randf_range(-40, 1192), -40)
		1: pos = Vector2(randf_range(-40, 1192), 688)
		2: pos = Vector2(-40, randf_range(-40, 688))
		3: pos = Vector2(1192, randf_range(-40, 688))
	enemy.global_position = pos
	add_child(enemy)
